//! Deterministic Rust-to-JSON-Schema projection primitives.
//!
//! The module fixes Schemars to Draft 2020-12, removes Rust editorial text,
//! rewrites only catalog-registered cross-resource definitions, and prunes
//! definitions unreachable from the selected resource roots.

use std::collections::{BTreeMap, BTreeSet, VecDeque};

use schemars::generate::SchemaSettings;
use schemars::{JsonSchema, Schema};

/// Projection behavior for one registered Rust schema producer.
///
/// This is the only catalog classification that changes generated bytes.
#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
pub(crate) enum ProjectionKind {
    /// Project one Rust type as the resource root.
    Root,
    /// Publish a related set of Rust-owned reusable definitions.
    DefinitionSet,
}

/// Trust transition required after one value passes structural validation.
///
/// This qualification is build-time evidence. It neither performs admission
/// nor introduces a generic runtime dispatcher. The descriptor manifest
/// remains the single owner of record authority and lifecycle metadata.
#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
pub(crate) enum AdmissionRoute {
    /// The portable wire type and its structural constraints are sufficient.
    StructuralOnly,
    /// The wire value can cross a fallible trust boundary without external
    /// context. No current root family uses this route.
    #[allow(
        dead_code,
        reason = "the closed qualification keeps the currently empty route explicit"
    )]
    ContextFree,
    /// The wire value requires its owner's typed context to become admitted.
    Contextual,
    /// The value is constructed by a named producer rather than admitted as
    /// independent external input.
    Generated,
}

/// One Rust-owned producer selected by the complete contract catalog.
///
/// Producers are generator inputs, not application-facing contract facades.
/// Custody, lifecycle, and persistence remain properties of the independently
/// admitted descriptor manifest.
#[derive(Clone, Copy)]
pub(crate) struct ContractProducer {
    schema_id: &'static str,
    projection_kind: ProjectionKind,
    admission_route: AdmissionRoute,
    project: fn() -> Schema,
    external_names: fn() -> Vec<String>,
}

impl ContractProducer {
    /// Register one exact Rust wire type as a schema producer.
    pub(crate) const fn typed<T: JsonSchema>(
        schema_id: &'static str,
        admission_route: AdmissionRoute,
    ) -> Self {
        Self {
            schema_id,
            projection_kind: ProjectionKind::Root,
            admission_route,
            project: project_type::<T>,
            external_names: external_type_name::<T>,
        }
    }

    /// Register a resource composed from multiple Rust-owned definitions.
    pub(crate) const fn definitions(
        schema_id: &'static str,
        admission_route: AdmissionRoute,
        project: fn() -> Schema,
        external_names: fn() -> Vec<String>,
    ) -> Self {
        Self {
            schema_id,
            projection_kind: ProjectionKind::DefinitionSet,
            admission_route,
            project,
            external_names,
        }
    }

    /// Return this producer's descriptor-manifest identity.
    #[must_use]
    pub(crate) const fn schema_id(self) -> &'static str {
        self.schema_id
    }

    /// Return the projection behavior that can affect generated bytes.
    #[must_use]
    pub(crate) const fn projection_kind(self) -> ProjectionKind {
        self.projection_kind
    }

    /// Return the trust transition required after structural validation.
    #[must_use]
    pub(crate) const fn admission_route(self) -> AdmissionRoute {
        self.admission_route
    }

    /// Return the Rust definition names owned by this resource.
    #[must_use]
    pub(crate) fn external_names(self) -> Vec<String> {
        (self.external_names)()
    }

    /// Project this producer as a Draft 2020-12 JSON value.
    ///
    /// `external_refs` maps Schemars-local definition references to their
    /// catalog-registered owning resources. Self references remain local.
    ///
    /// # Errors
    ///
    /// Returns an error for an invalid manifest URI, a boolean root, or a
    /// malformed local JSON Pointer encountered during pruning.
    pub(crate) fn project(
        self,
        schema_base_uri: &str,
        external_refs: &BTreeMap<String, ExternalDefinitionRef>,
    ) -> Result<serde_json::Value, String> {
        self.project_with_editorial_annotations(schema_base_uri, external_refs, false)
    }

    /// Project this producer for editor assistance while retaining Rust-owned
    /// descriptions and nested titles.
    ///
    /// This projection is not a portable contract resource and contributes to
    /// neither the descriptor manifest nor the active schema-set identity. It
    /// differs from [`Self::project`] only in editorial annotation retention;
    /// shape, constraints, references, pruning, and portable-integer checks are
    /// identical.
    pub(crate) fn project_for_authoring(
        self,
        schema_base_uri: &str,
        external_refs: &BTreeMap<String, ExternalDefinitionRef>,
    ) -> Result<serde_json::Value, String> {
        self.project_with_editorial_annotations(schema_base_uri, external_refs, true)
    }

    fn project_with_editorial_annotations(
        self,
        schema_base_uri: &str,
        external_refs: &BTreeMap<String, ExternalDefinitionRef>,
        retain_editorial_annotations: bool,
    ) -> Result<serde_json::Value, String> {
        validate_schema_base_uri(schema_base_uri)?;
        let mut schema = (self.project)().to_value();
        if !retain_editorial_annotations {
            strip_editorial_annotations(&mut schema);
        }
        rewrite_registered_refs(&mut schema, self.schema_id, external_refs);
        let retained_roots = if self.projection_kind == ProjectionKind::DefinitionSet {
            self.external_names()
        } else {
            Vec::new()
        };
        prune_unreachable_definitions(&mut schema, &retained_roots)?;
        let root = schema
            .as_object_mut()
            .ok_or_else(|| format!("{} producer returned a boolean schema", self.schema_id))?;
        root.insert(
            "$id".into(),
            format!("{schema_base_uri}{}.json", self.schema_id).into(),
        );
        root.insert("title".into(), self.schema_id.into());
        validate_portable_uint64_projections(&schema, self.schema_id)?;
        Ok(schema)
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct ExternalDefinitionRef {
    pub(crate) schema_id: &'static str,
    pub(crate) uri: String,
}

fn project_type<T: JsonSchema>() -> Schema {
    SchemaSettings::draft2020_12()
        .into_generator()
        .into_root_schema_for::<T>()
}

fn external_type_name<T: JsonSchema>() -> Vec<String> {
    vec![T::schema_name().into_owned()]
}

pub(crate) fn validate_schema_base_uri(value: &str) -> Result<(), String> {
    let Some(rest) = value
        .strip_prefix("https://")
        .or_else(|| value.strip_prefix("http://"))
    else {
        return Err("schema_base_uri must be an absolute HTTP(S) URI".into());
    };
    if rest.is_empty()
        || !value.ends_with('/')
        || value.contains('#')
        || value.contains('?')
        || value.chars().any(char::is_control)
    {
        return Err(
            "schema_base_uri must name an HTTP(S) directory without query or fragment".into(),
        );
    }
    Ok(())
}

fn rewrite_registered_refs(
    value: &mut serde_json::Value,
    current_schema_id: &str,
    external_refs: &BTreeMap<String, ExternalDefinitionRef>,
) {
    match value {
        serde_json::Value::Array(values) => {
            for value in values {
                rewrite_registered_refs(value, current_schema_id, external_refs);
            }
        }
        serde_json::Value::Object(object) => {
            if let Some(serde_json::Value::String(reference)) = object.get_mut("$ref") {
                if let Some(destination) = external_refs.get(reference) {
                    if destination.schema_id != current_schema_id {
                        reference.clone_from(&destination.uri);
                    }
                }
            }
            for value in object.values_mut() {
                rewrite_registered_refs(value, current_schema_id, external_refs);
            }
        }
        _ => {}
    }
}

fn strip_editorial_annotations(value: &mut serde_json::Value) {
    let Some(schema) = value.as_object_mut() else {
        return;
    };
    schema.remove("description");
    schema.remove("title");
    for keyword in [
        "additionalItems",
        "additionalProperties",
        "contains",
        "contentSchema",
        "else",
        "if",
        "items",
        "not",
        "propertyNames",
        "then",
        "unevaluatedItems",
        "unevaluatedProperties",
    ] {
        if let Some(subschema) = schema.get_mut(keyword) {
            strip_editorial_annotations(subschema);
        }
    }
    for keyword in ["allOf", "anyOf", "oneOf", "prefixItems"] {
        if let Some(subschemas) = schema
            .get_mut(keyword)
            .and_then(serde_json::Value::as_array_mut)
        {
            for subschema in subschemas {
                strip_editorial_annotations(subschema);
            }
        }
    }
    for keyword in [
        "$defs",
        "dependentSchemas",
        "patternProperties",
        "properties",
    ] {
        if let Some(subschemas) = schema
            .get_mut(keyword)
            .and_then(serde_json::Value::as_object_mut)
        {
            for subschema in subschemas.values_mut() {
                strip_editorial_annotations(subschema);
            }
        }
    }
}

/// Reject a generated numeric `u64` projection outside the portable JCS domain.
///
/// Rust producers own the individual constraint; this recursive postcondition
/// prevents a newly reachable definition or record field from silently escaping
/// the shared inclusive zero-to-[`pale_core::canon::JSON_SAFE_INTEGER_MAX`]
/// wire domain.
fn validate_portable_uint64_projections(
    value: &serde_json::Value,
    schema_id: &str,
) -> Result<(), String> {
    fn visit(
        value: &serde_json::Value,
        schema_id: &str,
        pointer: &mut Vec<String>,
    ) -> Result<(), String> {
        match value {
            serde_json::Value::Array(values) => {
                for (index, value) in values.iter().enumerate() {
                    pointer.push(index.to_string());
                    visit(value, schema_id, pointer)?;
                    pointer.pop();
                }
            }
            serde_json::Value::Object(object) => {
                if object.get("format").and_then(serde_json::Value::as_str) == Some("uint64") {
                    let has_nonnegative_minimum = object
                        .get("minimum")
                        .and_then(serde_json::Value::as_u64)
                        .is_some();
                    let has_portable_maximum = object
                        .get("maximum")
                        .and_then(serde_json::Value::as_u64)
                        .is_some_and(|maximum| maximum <= pale_core::canon::JSON_SAFE_INTEGER_MAX);
                    if !has_nonnegative_minimum || !has_portable_maximum {
                        let location = pointer
                            .iter()
                            .map(|token| escape_pointer_token(token))
                            .collect::<Vec<_>>()
                            .join("/");
                        return Err(format!(
                            "{schema_id} projects a uint64 outside the portable JCS domain at /{location}"
                        ));
                    }
                }
                for (key, value) in object {
                    pointer.push(key.clone());
                    visit(value, schema_id, pointer)?;
                    pointer.pop();
                }
            }
            _ => {}
        }
        Ok(())
    }

    visit(value, schema_id, &mut Vec::new())
}

fn prune_unreachable_definitions(
    value: &mut serde_json::Value,
    retained_roots: &[String],
) -> Result<(), String> {
    let root = value
        .as_object_mut()
        .ok_or_else(|| "generated schema root is not an object".to_string())?;
    let Some(definitions) = root.remove("$defs") else {
        return Ok(());
    };
    let definitions = definitions
        .as_object()
        .ok_or_else(|| "generated $defs is not an object".to_string())?;
    let mut reachable = BTreeSet::new();
    let mut pending = retained_roots.iter().cloned().collect::<VecDeque<_>>();
    pending.extend(local_definition_refs(&serde_json::Value::Object(
        root.clone(),
    ))?);
    while let Some(name) = pending.pop_front() {
        if !reachable.insert(name.clone()) {
            continue;
        }
        let definition = definitions
            .get(&name)
            .ok_or_else(|| format!("generated schema has unresolved local definition `{name}`"))?;
        pending.extend(local_definition_refs(definition)?);
    }
    let retained = definitions
        .iter()
        .filter(|(name, _)| reachable.contains(name.as_str()))
        .map(|(name, definition)| (name.clone(), definition.clone()))
        .collect::<serde_json::Map<_, _>>();
    if !retained.is_empty() {
        root.insert("$defs".into(), serde_json::Value::Object(retained));
    }
    Ok(())
}

fn local_definition_refs(value: &serde_json::Value) -> Result<VecDeque<String>, String> {
    fn collect(value: &serde_json::Value, found: &mut VecDeque<String>) -> Result<(), String> {
        match value {
            serde_json::Value::Array(values) => {
                for value in values {
                    collect(value, found)?;
                }
            }
            serde_json::Value::Object(object) => {
                if let Some(reference) = object.get("$ref").and_then(serde_json::Value::as_str) {
                    if let Some(name) = reference.strip_prefix("#/$defs/") {
                        found.push_back(unescape_pointer_token(name)?);
                    }
                }
                for value in object.values() {
                    collect(value, found)?;
                }
            }
            _ => {}
        }
        Ok(())
    }

    let mut found = VecDeque::new();
    collect(value, &mut found)?;
    Ok(found)
}

fn unescape_pointer_token(token: &str) -> Result<String, String> {
    let mut output = String::with_capacity(token.len());
    let mut chars = token.chars();
    while let Some(character) = chars.next() {
        if character != '~' {
            output.push(character);
            continue;
        }
        match chars.next() {
            Some('0') => output.push('~'),
            Some('1') => output.push('/'),
            _ => return Err(format!("invalid JSON Pointer token `{token}`")),
        }
    }
    Ok(output)
}

pub(crate) fn escape_pointer_token(token: &str) -> String {
    token.replace('~', "~0").replace('/', "~1")
}

pub(crate) fn definition_set(collect: impl FnOnce(&mut schemars::SchemaGenerator)) -> Schema {
    let mut generator = SchemaSettings::draft2020_12().into_generator();
    collect(&mut generator);
    let definitions = generator.take_definitions(true);
    schemars::json_schema!({
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "not": {},
        "$defs": definitions
    })
}

